<script setup>
import { computed } from 'vue'
const props = defineProps({
  width: { type: String, default: '100%' },
  height: { type: String, default: '100vw' },
  rotate: { type: Number, default: 0 },
  style: { type: Object, default: () => ({}) }
})

const computedTransform = computed(() => {
  const r = Number(props.rotate) || 0
  // When rotating 90 or 270 deg around top-left, the element moves up out of view.
  // Translate it down by its height to keep it within the container.
  if (Math.abs(r % 180) === 90) {
    return `translateX(${props.height}) rotate(${r}deg)`
  }
  return `rotate(${r}deg)`
})
</script>